"""Build the self-contained offline 3D viewer and its engineering summary."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]

def main():
    mesh=(ROOT/'viewer'/'mesh.json').read_text()
    p=json.loads((ROOT/'selected_design.json').read_text());r=json.loads((ROOT/'analysis'/'results.json').read_text())['scenarios']['selected']
    html=TEMPLATE.replace('__MESH__',mesh).replace('__STATS__',json.dumps(dict(mass=round(r['mass_kg']),span=p['wing_span_m'],diameter=p['rotor_diameter_m'],speed=p['cruise_kph'],hover=round(r['hover_electrical_kw']),range=round(r['energy_based_range_km'],1))))
    (ROOT/'viewer'/'E8_3D_Viewer_Offline.html').write_text(html)

TEMPLATE='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"><title>E8 Aircraft · Offline 3D Assembly</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf1f3;color:#162b3b;font:14px system-ui}header{background:#152e41;color:#fff;padding:22px 30px;display:flex;justify-content:space-between;align-items:center}h1{font-size:23px;margin:4px 0}small{letter-spacing:2px;color:#a9c2ce}header span{background:#2a4b60;padding:8px 12px;border-radius:18px}main{display:grid;grid-template-columns:290px 1fr;min-height:78vh}aside{padding:22px;background:white;border-right:1px solid #d1dce2}h2{font-size:14px;letter-spacing:1px;text-transform:uppercase;margin:24px 0 10px}label{display:block;margin:10px 0;cursor:pointer}input[type=range]{width:100%;accent-color:#167d87}input[type=checkbox]{accent-color:#167d87}button{background:#edf3f5;border:1px solid #ccd8df;padding:9px 11px;border-radius:5px;margin:3px;color:#17394d;cursor:pointer}button:hover{background:#d4e6e9}.stage{position:relative;min-height:650px;overflow:hidden;background:linear-gradient(#f3f6f8,#e3eaf0)}canvas{display:block;width:100%;height:100%;min-height:650px;touch-action:none;cursor:grab}.hint{position:absolute;left:20px;bottom:18px;pointer-events:none;color:#557083;font-size:12px}.tag{position:absolute;right:18px;top:18px;background:#fff;padding:10px 15px;border:1px solid #d0dbe0;border-radius:7px}.note{padding:16px 28px;background:#fff4df;border-top:1px solid #e5cba0;font-size:13px;line-height:1.6}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:18px 25px;background:white}.stats div{padding:12px;border-left:3px solid #16838c}.stats b{font-size:19px;display:block}.stats span{font-size:12px;color:#607785}.muted{font-size:12px;color:#657b89;line-height:1.5}#selection{font-size:12px;line-height:1.6;color:#427080;min-height:28px}footer{padding:15px 28px;color:#657b89;font-size:12px}@media(max-width:800px){header{padding:15px}header span{display:none}main{display:flex;flex-direction:column}aside{padding:15px;border:0}.stage,canvas{min-height:460px;height:460px}.stats{grid-template-columns:repeat(2,1fr)}h2{margin-top:12px}.layers{display:grid;grid-template-columns:1fr 1fr}}
</style></head><body><header><div><small>ENGINEERING CONCEPT / E8 · 0.1</small><h1>Two seats. Eight tilting rotors.</h1></div><span>Self-contained · works offline</span></header><main><aside><p class="muted">Drag to orbit. Scroll to zoom. Select a configuration and inspect the assembly.</p><h2>Configuration</h2><label><input id="wing" type="checkbox" checked> Wing and tail installed</label><label>Rotor tilt <b id="tiltValue">0° · hover</b><input id="tilt" type="range" min="0" max="90" value="0"></label><label>Exploded view<input id="explode" type="range" min="0" max="100" value="0"></label><h2>View</h2><div><button data-view="iso">Isometric</button><button data-view="top">Top</button><button data-view="side">Side</button><button data-view="front">Front</button></div><h2>Layers</h2><div class="layers" id="layers"></div><label><input id="disks" type="checkbox"> Rotor disk envelopes</label><button id="reset">Reset</button><p id="selection"></p><p class="muted">Rotor blades, motor housings and systems are geometric envelopes. Tilt animation shows placement only; it does not simulate transition or certify clearances.</p></aside><section class="stage"><canvas id="view" aria-label="Interactive three-dimensional aircraft assembly"></canvas><div class="tag" id="tag"></div><div class="hint">Nose = −X · Y = lateral · Z = up · dimensions in metres</div></section></main><div class="stats" id="stats"></div><div class="note"><strong>Preliminary concept — no fabrication or flight release.</strong> The energy minimum is from a bounded conceptual trade study. Battery thermal rejection, exact propeller matching, composite joints, rotor-out control and flight stability remain open. See the included design report and independent reviews. Removing the wing is a conceptual alternative, not a validated flight configuration.</div><footer>No network requests, accounts or external libraries. Download the STEP/FreeCAD files from the repository for CAD work.</footer><script>
'use strict';const mesh=__MESH__, stats=__STATS__, canvas=document.getElementById('view'), ctx=canvas.getContext('2d');let yaw=-.62,pitch=.42,zoom=1,dragging=false,last=null;const visibility={airframe:true,canopy:true,structure:true,aero:true,rotor:true,motor:true,battery:true,systems:true,cabin:true,gear:true};
const names={airframe:'Fuselage shell',canopy:'Canopy',structure:'Frame and spars',aero:'Aerodynamic envelopes',rotor:'Blade silhouettes',motor:'Motors and hubs',battery:'Battery modules',systems:'Systems envelopes',cabin:'Cabin and seats',gear:'Landing gear'};
const $=id=>document.getElementById(id);for(const [k,v]of Object.entries(names)){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=true;input.dataset.layer=k;input.addEventListener('change',()=>{visibility[k]=input.checked;draw()});label.append(input,document.createTextNode(' '+v));$('layers').append(label)}
$('stats').innerHTML=[['Mass incl. allowances',stats.mass+' kg'],['Wing span',stats.span+' m'],['Rotor diameter',stats.diameter+' m'],['Cruise point',stats.speed+' km/h'],['Hover electrical estimate',stats.hover+' kW'],['Energy-based range',stats.range+' km']].map(([a,b])=>'<div><b>'+b+'</b><span>'+a+' · winged reference</span></div>').join('');
function transform(v,part,tilt,explode){let [x,y,z]=v;if(part.rotor!==undefined){let p=part.pivot_mm.map(x=>x/1000),a=tilt*Math.PI/180,dx=x-p[0],dz=z-p[2];x=p[0]+dx*Math.cos(a)-dz*Math.sin(a);z=p[2]+dx*Math.sin(a)+dz*Math.cos(a)}if(explode){let shift=part.category==='aero'?1.1:part.category==='airframe'?-.2:part.category==='canopy'?2:part.category==='battery'?-1.6:0;z+=shift*explode;if(part.rotor!==undefined){x+=Math.sign(x)*explode*.5;y+=Math.sign(y)*explode*.6}}return [x,y,z]}
function camera(v){let x=v[0]*Math.cos(yaw)-v[1]*Math.sin(yaw),d=v[0]*Math.sin(yaw)+v[1]*Math.cos(yaw);return [x,v[2]*Math.cos(pitch)-d*Math.sin(pitch),v[2]*Math.sin(pitch)+d*Math.cos(pitch)]}
let frame=0;function draw(){cancelAnimationFrame(frame);frame=requestAnimationFrame(render)}
function render(){let w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==w*dpr||canvas.height!==h*dpr){canvas.width=w*dpr;canvas.height=h*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);let scale=Math.min(w/13,h/9)*zoom,ox=w*.5,oy=h*.57,tilt=+$('tilt').value,ex=+$('explode').value/100,wing=$('wing').checked;const screen=v=>[ox+v[0]*scale,oy-v[1]*scale];
ctx.lineWidth=.6;ctx.strokeStyle='#d5dfe5';for(let i=-7;i<=7;i++){for(const edge of [[[-7,i,-1.25],[7,i,-1.25]],[[i,-7,-1.25],[i,7,-1.25]]]){let a=screen(camera(edge[0])),b=screen(camera(edge[1]));ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}}
let faces=[],count=0;for(const part of mesh){if(!visibility[part.category]||(!wing&&part.wing_only))continue;count++;let vs=part.vertices.map(v=>camera(transform(v,part,tilt,ex)));for(const t of part.triangles){let a=vs[t[0]],b=vs[t[1]],c=vs[t[2]],ab=b.map((v,i)=>v-a[i]),ac=c.map((v,i)=>v-a[i]),nx=ab[1]*ac[2]-ab[2]*ac[1],ny=ab[2]*ac[0]-ab[0]*ac[2],nz=ab[0]*ac[1]-ab[1]*ac[0],norm=Math.hypot(nx,ny,nz)||1,shade=.65+.35*Math.abs((nx*.25+ny*.4+nz*.85)/norm);faces.push({p:[screen(a),screen(b),screen(c)],d:(a[2]+b[2]+c[2])/3,c:part.color.map(v=>Math.round(v*255*shade))})}}
faces.sort((a,b)=>a.d-b.d);for(const f of faces){ctx.beginPath();ctx.moveTo(...f.p[0]);ctx.lineTo(...f.p[1]);ctx.lineTo(...f.p[2]);ctx.closePath();ctx.fillStyle='rgb('+f.c.join(',')+')';ctx.fill()}
if($('disks').checked){for(let i=0;i<8;i++){let part=mesh.find(p=>p.rotor===i&&p.category==='rotor'),p=part.pivot_mm.map(v=>v/1000);ctx.beginPath();for(let j=0;j<=64;j++){let a=j*Math.PI/32,v=[p[0]+stats.diameter/2*Math.cos(a),p[1]+stats.diameter/2*Math.sin(a),p[2]+.4],s=screen(camera(transform(v,part,tilt,ex)));j?ctx.lineTo(...s):ctx.moveTo(...s)}ctx.strokeStyle='#167f9aaa';ctx.lineWidth=1;ctx.stroke()}}
$('tag').textContent=(wing?'Winged':'Wingless')+' · '+count+' visible components';$('selection').textContent=mesh.length+' named CAD components · '+(ex?'exploded view':'assembled view');$('tiltValue').textContent=tilt+'° · '+(tilt===0?'hover':tilt===90?'cruise placement':'transition placement')}
canvas.addEventListener('pointerdown',e=>{dragging=true;last=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointermove',e=>{if(!dragging)return;yaw+=(e.clientX-last[0])*.008;pitch=Math.max(-1.55,Math.min(1.55,pitch+(e.clientY-last[1])*.008));last=[e.clientX,e.clientY];draw()});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.45,Math.min(3,zoom*Math.exp(-e.deltaY*.001)));draw()},{passive:false});for(const id of ['wing','tilt','explode','disks'])$(id).addEventListener('input',draw);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{[yaw,pitch]=({iso:[-.62,.42],top:[0,Math.PI/2],side:[0,0],front:[Math.PI/2,0]})[b.dataset.view];draw()});$('reset').onclick=()=>{yaw=-.62;pitch=.42;zoom=1;$('tilt').value=0;$('explode').value=0;$('wing').checked=true;$('disks').checked=false;for(const k in visibility)visibility[k]=true;document.querySelectorAll('[data-layer]').forEach(x=>x.checked=true);draw()};new ResizeObserver(draw).observe(canvas);draw();
</script></body></html>'''
if __name__=='__main__':main()
